 "content": "def transform(grid):
    """For each complete square 2-frame, fill its zero interior with the
    number of interior zero cells modulo 10, preserving interior 2s."""
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    for r0 in range(h - 2):
        for r1 in range(r0 + 2, h):
            side_delta = r1 - r0
            for c0 in range(w - side_delta):
                c1 = c0 + side_delta
                if not (all(grid[r0][c] == 2 for c in range(c0, c1 + 1))
                        and all(grid[r1][c] == 2 for c in range(c0, c1 + 1))
                        and all(grid[r][c0] == 2 for r in range(r0, r1 + 1))
                        and all(grid[r][c1] == 2 for r in range(r0, r1 + 1))):
                    continue
                interior = [(r, c) for r in range(r0 + 1, r1)
                            for c in range(c0 + 1, c1)]
                fill = sum(grid[r][c] == 0 for r, c in interior) % 10
                for r, c in interior:
                    if grid[r][c] == 0:
                        out[r][c] = fill
    return out
